// internal/distributed/proxy/httpserver/timeout_middleware.go lines 183-186
func timeoutMiddleware(handler gin.HandlerFunc) gin.HandlerFunc {
    ...
    timeoutSecond, err := strconv.ParseInt(gCtx.Request.Header.Get(mhttp.HTTPHeaderRequestTimeout), 10, 64)
    if err == nil {
        timeout = time.Duration(timeoutSecond) * time.Second
    }
    ...
}

// BUG: ParseInt fails for non-integer values (abc, 3.5), returning err. The code silently ignores err and falls back to default timeout instead of rejecting the request with HTTP 400.
